data.userPrompt:
Here is the list of regression test cases names to execute (testCaseName):
{{node:js-1.output}}

Execute each one using the run_regression_test tool, one at a time, then return the final JSON object as instructed.

data.code:
const data = input || {};
const counts = data.counts || {};
const summary = data.summary || '';
const tests = Array.isArray(data.tests) ? data.tests : [];

function norm(s) { return String(s || 'unknown').toLowerCase(); }
function esc(s) {
  return String(s == null ? '' : s)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

const successCount = counts.success != null ? counts.success : tests.filter(t => norm(t.status) === 'success').length;
const failedCount = counts.failed != null ? counts.failed : tests.filter(t => norm(t.status) === 'failed').length;
const brokenCount = counts.broken != null ? counts.broken : tests.filter(t => norm(t.status) === 'broken').length;

function renderTest(t) {
  const st = norm(t.status);
  const name = t.name || t.testCaseName || 'Unnamed test';
  return '<div class="test-item" data-status="' + st + '">' +
    '<div class="test-header"><span class="badge badge-' + st + '">' + esc(t.status) + '</span>' +
    '<span class="test-name">' + esc(name) + '</span></div>' +
    '<div class="test-body"><p><strong>Last step:</strong> ' + esc(t.lastStep || t.last_step || 'N/A') + '</p>' +
    '<p><strong>Reason:</strong> ' + esc(t.reason || t.details || 'N/A') + '</p></div></div>';
}

const testsHtml = tests.map(renderTest).join('');

const css = 'body{font-family:Arial,Helvetica,sans-serif;background:#f4f6f8;color:#222;margin:0;padding:20px;}' +
  '.container{max-width:800px;margin:0 auto;background:#fff;border-radius:8px;padding:24px;box-shadow:0 2px 8px rgba(0,0,0,0.08);}' +
  'h1{font-size:20px;margin-top:0;}' +
  '.summary-text{background:#f0f4f8;padding:14px;border-radius:6px;margin-bottom:20px;line-height:1.5;}' +
  '.counts{display:flex;gap:12px;margin-bottom:20px;flex-wrap:wrap;}' +
  '.count-box{flex:1;min-width:100px;text-align:center;padding:14px;border-radius:8px;color:#fff;font-weight:bold;}' +
  '.count-success{background:#2ecc71;} .count-failed{background:#e74c3c;} .count-broken{background:#f39c12;}' +
  '.filters{margin-bottom:16px;}' +
  '.filters button{border:none;padding:8px 16px;margin-right:8px;border-radius:20px;cursor:pointer;font-size:13px;background:#e0e0e0;}' +
  '.filters button.active{background:#2d3748;color:#fff;}' +
  '.test-item{border-left:4px solid #ccc;margin-bottom:12px;padding:12px 14px;border-radius:6px;background:#fafafa;}' +
  '.test-item[data-status="success"]{border-color:#2ecc71;background:#eafaf1;}' +
  '.test-item[data-status="failed"]{border-color:#e74c3c;background:#fdecea;}' +
  '.test-item[data-status="broken"]{border-color:#f39c12;background:#fff7e6;}' +
  '.test-header{display:flex;align-items:center;margin-bottom:6px;}' +
  '.badge{padding:2px 10px;border-radius:12px;color:#fff;font-size:11px;margin-right:10px;text-transform:uppercase;}' +
  '.badge-success{background:#2ecc71;} .badge-failed{background:#e74c3c;} .badge-broken{background:#f39c12;} .badge-unknown{background:#999;}' +
  '.test-name{font-weight:bold;}' +
  '.test-item.hidden{display:none;}';

const script = "function filterTests(status){" +
  "var items=document.querySelectorAll('.test-item');" +
  "items.forEach(function(el){var s=el.getAttribute('data-status');" +
  "if(status==='all'||s===status){el.classList.remove('hidden');}else{el.classList.add('hidden');}});" +
  "var btns=document.querySelectorAll('.filters button');" +
  "btns.forEach(function(b){b.classList.remove('active');if(b.getAttribute('data-filter')===status){b.classList.add('active');}});" +
  "}";

const html = '<!DOCTYPE html><html><head><meta charset="utf-8"><style>' + css + '</style></head><body>' +
  '<div class="container"><h1>Regression Test Report</h1>' +
  '<div class="summary-text">' + esc(summary) + '</div>' +
  '<div class="counts">' +
  '<div class="count-box count-success">Success: ' + successCount + '</div>' +
  '<div class="count-box count-failed">Failed: ' + failedCount + '</div>' +
  '<div class="count-box count-broken">Broken: ' + brokenCount + '</div>' +
  '</div>' +
  '<div class="filters">' +
  '<button data-filter="all" class="active" onclick="filterTests(\'all\')">All</button>' +
  '<button data-filter="success" onclick="filterTests(\'success\')">Success</button>' +
  '<button data-filter="failed" onclick="filterTests(\'failed\')">Failed</button>' +
  '<button data-filter="broken" onclick="filterTests(\'broken\')">Broken</button>' +
  '</div>' +
  '<div class="tests">' + testsHtml + '</div>' +
  '</div>' +
  '<script>' + script + '</script>' +
  '</body></html>';

output = html;

const counts = input.counts || {};
const dateStr = new Date().toISOString().slice(0,10);
const subject = 'Regression Test Report (' + dateStr + ') - Success: ' + (counts.success||0) + ', Failed: ' + (counts.failed||0) + ', Broken: ' + (counts.broken||0);
const payload = {
  message: {
    subject: subject,
    body: { contentType: 'HTML', content: input.html },
    toRecipients: [ { emailAddress: { address: 'Recipient@test.ai' } } ]
  },
  saveToSentItems: 'true'
};
output = JSON.stringify(payload);

function getLeafResult(call) {
  if (!call) return null;
  const res = call.result || call.output || {};
  const nested = res.Result || res.result;
  if (Array.isArray(nested) && nested.length > 0) {
    return getLeafResult(nested[nested.length - 1]);
  }
  return res;
}

const calls = Array.isArray(input) ? input : (input && input.toolCalls) || [];
const last = calls.length ? calls[calls.length - 1] : null;
const result = getLeafResult(last);
return { result };
